using System;
using System.Collections.Generic;
using UnityEngine;

namespace MixMaster.Core
{
    /// <summary>
    /// Runtime lookup for equipment definitions generated by CSV import.
    /// </summary>
    [CreateAssetMenu(fileName = "EquipmentCatalog",
        menuName = "MixMaster/Data/Equipment Catalog")]
    public sealed class EquipmentCatalogSO : ScriptableObject
    {
        public const string ResourcesPath = "Data/EquipmentCatalog";

        [SerializeField] private List<EquipmentSO> equipment =
            new List<EquipmentSO>();

        private Dictionary<string, EquipmentSO> byId;
        private static EquipmentCatalogSO cached;

        public IReadOnlyList<EquipmentSO> Equipment => equipment;

        public static EquipmentCatalogSO Load()
        {
            if (cached == null)
                cached = Resources.Load<EquipmentCatalogSO>(ResourcesPath);
            return cached;
        }

        public EquipmentSO GetEquipment(string equipmentId)
        {
            if (string.IsNullOrWhiteSpace(equipmentId))
                return null;

            if (byId == null)
                BuildLookup();

            byId.TryGetValue(equipmentId, out EquipmentSO found);
            return found;
        }

        public void SetData(List<EquipmentSO> definitions)
        {
            equipment = definitions ?? new List<EquipmentSO>();
            byId = null;
        }

        private void BuildLookup()
        {
            byId = new Dictionary<string, EquipmentSO>(
                StringComparer.OrdinalIgnoreCase);

            if (equipment == null)
                return;

            foreach (EquipmentSO definition in equipment)
            {
                if (definition == null ||
                    string.IsNullOrWhiteSpace(definition.equipmentId) ||
                    byId.ContainsKey(definition.equipmentId))
                    continue;

                byId.Add(definition.equipmentId, definition);
            }
        }

#if UNITY_EDITOR
        private void OnValidate()
        {
            byId = null;
        }
#endif
    }
}
